package com.alameer.my;

import java.util.HashMap;
import java.util.Map;

// Generated at build time from the wrapped site's HTML/CSS/JS. Each
// file's bytes are stored base64-encoded as a compiled string constant
// (part of classes.dex), not as a loose file under assets/.
// MainActivity's shouldInterceptRequest override (see EMBED_HOST) decodes
// these on demand to feed the WebView, in place of the OS resolving
// file:///android_asset/ requests against a real assets/ folder.
public final class EmbeddedAssets {
    // Joins base64 chunks at class-init time. Deliberately NOT string
    // concatenation on the call site (see the comment above each F<n>
    // field) -- a method call is not a compile-time constant expression,
    // so javac can't fold these chunks back into one oversized constant.
    private static String join(String... parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) sb.append(p);
        return sb.toString();
    }

    private static final String F0 = join(
            "",
            "",
            "",
            "");

    private static final String F1 = join(
            UrlObfuscator.decode(new int[] { 74, 55, 39, 249, 242, 157, 216, 100, 110, 44, 10, 237, 145, 155, 185, 89, 109, 74, 52, 5, 169, 227, 187, 162, 126, 95, 20, 0, 218, 252, 188, 182, 61, 101, 39, 54, 226, 222, 160, 221, 53, 109, 35, 61, 242, 203, 133, 185, 143, 39, 80, 25, 73, 214, 233, 130, 159, 98, 92, 34, 65, 203, 219, 138, 134, 122, 68, 63, 34, 196, 192, 167, 213, 95, 71, 30, 11, 193, 232, 179, 150, 144, 83, 83, 57, 73, 211, 136, 143, 196, 32, 92, 49, 37, 196, 217, 128, 135, 65, 118, 35, 14, 224, 221, 245, 170, 73, 126, 43, 22, 236, 235, 246, 183, 138, 117, 89, 29, 63, 237, 237, 175, 188, 34, 122, 63, 55, 233, 230, 167, 154, 101, 113, 13, 5, 241, 238, 172, 138, 109, 64, 44, 51, 243, 214, 215, 170, 149, 120, 9, 11, 16, 244, 216, 135, 146, 119, 106, 27, 3, 198, 196, 162, 133, 71, 67, 112, 24, 229, 203, 151, 136, 102, 97, 116, 15, 27, 217, 140, 175, 178, 115, 78, 49, 45, 209, 217, 174, 144, 85, 73, 56, 10, 221, 228, 250, 162, 100, 103, 120, 62, 209, 144, 175, 186, 85, 89, 54, 61, 19, 200, 213, 151, 185, 83, 81, 14, 33, 219, 198, 137, 193, 91, 70, 43, 57, 184, 199, 147, 216, 71, 94, 37, 33, 188, 221, 138, 136, 110, 73, 118, 108, 36, 230, 225, 176, 163, 117, 110, 63, 60, 231, 250, 188, 163, 127, 117, 25, 92, 224, 243, 248, 167, 126, 69, 1, 92, 253, 234, 168, 142, 105, 86, 68, 28, 79, 213, 237, 139, 145, 89, 101, 31, 77, 208, 213, 236, 205 }, 47));

    private static final String F2 = join(
            "");

    private static final Map<String, String> MAP = new HashMap<>();
    static {
        MAP.put(UrlObfuscator.decode(new int[] { 41, 49, 26, 248, 196, 245, 146, 109, 85, 59 }, 64), F0);
        MAP.put(UrlObfuscator.decode(new int[] { 60, 17, 225, 199, 171, 137, 120, 94, 103, 31, 226, 196, 168, 133, 109, 75, 39, 5, 12, 234 }, 81), F1);
        MAP.put(UrlObfuscator.decode(new int[] { 17, 246, 142, 213, 173 }, 98), F2);
    }

    // rel: path as it would have appeared under assets/, e.g. "index.html"
    // or "css/style.css". Returns null if nothing was embedded at that path.
    public static byte[] get(String rel) {
        String b64 = MAP.get(rel);
        if (b64 == null) return null;
        byte[] raw = android.util.Base64.decode(b64, android.util.Base64.DEFAULT);
        return raw;
    }

    private EmbeddedAssets() {}
}
